module fir_decimator_8x_ip (
  clk,
  rstn,
  fir_rfi_o,
  fir_valid_i,
  fir_sync_i,
  fir_data_i,
  fir_valid_o,
  fir_sync_o,
  fir_data_o
)
;
input clk;
input rstn;
output fir_rfi_o;
input fir_valid_i;
input fir_sync_i;
input [15:0] fir_data_i;
output fir_valid_o;
output fir_sync_o;
output [32:0] fir_data_o;
wire VCC;
wire GND;
  \(advanced_fir_filter)/(fir_decimator_8x_ip)(COEFF_WIDTH=18,DOUT_WIDTH=33,TAPS_SIZE=128,NUM_CHN=1,NUM_TDM=8,NUM_FACTOR=8,COEFF_PATH="./coeff.dat")  advanced_fir_filter_inst (
    .clk(clk),
    .fir_valid_i(fir_valid_i),
    .fir_sync_i(fir_sync_i),
    .rstn(rstn),
    .fir_data_i(fir_data_i[15:0]),
    .fir_valid_o(fir_valid_o),
    .fir_rfi_o(fir_rfi_o),
    .fir_data_o(fir_data_o[32:0])
);
  VCC VCC_cZ (
    .V(VCC)
);
  GND GND_cZ (
    .G(GND)
);
  GSR GSR (
    .GSRI(VCC) 
);
assign fir_sync_o = fir_valid_o;
endmodule /* fir_decimator_8x_ip */
